/* Connected workspace views. All records remain studio data for this session. */
let routeParts = [], projectMode = 'board', agendaMode = 'week';
let ticketScope = 'All tickets', financeTab = 'overview', companyTab = 'team';
/* On a new day the page is drawn again. Once data is loaded, store.js owns the
   repaint (it reloads the week's events on the same signal), and agenda-ui.js
   moves the agenda on with the date; before that there is nothing to wait for.
   Either way the repaint waits for any half-written draft — see
   repaintWhenIdle in app.js. */
CAL.onChange(()=>{if(!(window.workspaceStore&&workspaceStore.state.loaded))repaintWhenIdle();});
const queries = {tickets:'', projects:'', crm:'', mail:'', finance:''};


const originalOverview = overview, originalAction = action;
const matches =(q,...values) => values.join(' ').toLowerCase().includes(q.toLowerCase().trim());
const link = (route,label,ic='arrow',cls='text-btn') => `<a href="#${esc(route)}" class="${cls}">${ic?icon(ic):''}<span>${esc(label)}</span></a>`;
const empty = (title,body) => `<div class="workspace-empty">${icon('search')}<h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;
const countTag = n => `<span class="small-count">${n}</span>`;
const titlebar = (title,subtitle,button='') => `<div class="page-heading app-heading"><div><div class="app-eyebrow">${icon(page)}<span>VEYAGO ${esc(navs.find(n=>n[0]===page)?.[1]||'WORKSPACE').toUpperCase()}</span></div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${button?`<div class="heading-actions">${button}</div>`:''}</div>`;
const createButton = (label,kind) => `<button class="btn btn-primary" data-create="${kind}">${icon('plus')}${label}</button>`;
const statStrip = items => `<div class="stat-strip">${items.map(([label,value,hint])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong>${hint?`<small>${esc(hint)}</small>`:''}</div>`).join('')}</div>`;
function queryInput(key,placeholder){return `<div class="list-search">${icon('search')}<input type="search" data-query="${key}" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(queries[key])}"></div>`;}
function segments(items,current,key){return `<div class="tabs" aria-label="View options">${items.map(([value,label])=>`<button data-view="${key}" data-value="${value}" class="${current===value?'active':''}" aria-pressed="${current===value}">${label}</button>`).join('')}</div>`;}
function detailHeader(parent,label,title,subtitle,actions=''){return `<div class="detail-back">${link(parent,label,'chevron')}</div>${titlebar(title,subtitle,actions)}`;}
function subnav(items,current){return `<nav class="subnav" aria-label="Page sections">${items.map(([path,label,key])=>`<a href="#${path}" class="${current===key?'selected':''}" ${current===key?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav>`;}
function properties(rows){return `<section class="panel property-panel"><h2>Details</h2>${rows.map(([k,v])=>`<div class="property-row"><span>${k}</span><div>${v}</div></div>`).join('')}</section>`;}
function selectField(label,kind,id,field,values,current){return `<select aria-label="${label}" data-record-kind="${kind}" data-record-id="${esc(id)}" data-field="${field}">${values.map(v=>`<option ${current===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`;}
function noteCharacters(s){return typeof Intl!=='undefined'&&Intl.Segmenter?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(s),part=>part.segment):Array.from(s);}function noteControls(n){const s=window.workspaceSession,e=s&&s.employee;if(!n.id||!e||typeof tasksModel==='undefined')return '';const viewer={id:e.id,role:e.role,status:e.status},mine=tasksModel.canEditNote(viewer,n),words=noteCharacters(String(n.body==null?'':n.body).trim().replace(/\s+/g,' ')),about=': “'+(words.length>40?words.slice(0,39).join('')+'…':words.join(''))+'”',edit=mine?`<button type="button" class="text-btn" data-note-edit="${esc(n.id)}" aria-label="${esc('Edit your note from '+n.time+about)}">Edit</button>`:'',remove=tasksModel.canDeleteNote(viewer,n)?`<button type="button" class="text-btn" data-note-remove="${esc(n.id)}" aria-label="${esc('Remove '+(mine?'your note':n.authorId?(n.who||'Someone')+'’s note':'a former team member’s note')+' from '+n.time+about)}">Remove</button>`:'';return edit||remove?`<div class="note-controls">${edit}${remove}</div>`:'';}function noteFeed(kind,id){let notes=recordNotes[kind][id]||[];if(!notes.length)return window.workspaceStore&&typeof workspaceStore.has==='function'&&!workspaceStore.has('notes')?'<p class="quiet-text">Notes did not load. They are tried again by themselves.</p>':'<p class="quiet-text">No notes yet. Add context for your next step.</p>';return notes.map(n=>`<article class="conversation-entry"><div class="avatar owner">${esc(n.initial||'V')}</div><div><div class="message-meta"><strong>${esc(n.who||'Veyago')}</strong><span>${esc(n.label||'Internal note')} · ${esc(n.time)}</span></div><p>${esc(n.body)}</p>${noteControls(n)}</div></article>`).join('');}
function noteForm(kind,id,label='Add a note'){return `<form class="note-form" data-note-form="${kind}" data-record-id="${esc(id)}"><label for="record-note">${label}</label><textarea id="record-note" name="note" required placeholder="Add an update, decision, or next step…">${esc(window.noteDrafts?window.noteDrafts.get(kind,id):'')}</textarea><div class="form-bottom"><span>Saved to the record</span><button class="btn btn-primary" type="submit">Save note</button></div></form>`;}
function notesPanel(kind,id){return `<section class="panel content-panel"><h2>Notes & updates</h2><div class="conversation-feed">${noteFeed(kind,id)}</div>${noteForm(kind,id)}</section>`;}
function activityRecord(message){workspaceActivity.unshift({text:message,when:'Just now'});}
function linkedPanel(title,items){return `<section class="panel content-panel related-panel"><h2>${title}</h2>${items.length?items.map(([route,label,meta,ic])=>`<a href="#${esc(route)}" class="related-item"><span class="related-icon">${icon(ic)}</span><div><strong>${esc(label)}</strong><small>${esc(meta)}</small></div>${icon('chevron')}</a>`).join(''):'<p class="quiet-text">No linked records yet.</p>'}</section>`;}
function notFound(){return `${detailHeader(page,'Back to '+page,'This record is unavailable.','Open another record from the app.')}<section class="panel">${empty('Record not found','It may have been removed, or this link is out of date.')}</section>`;}
function checkedTasks(p){return p.checked?.length||0;}
/* Who owns a project: the team member with its owner_id, not whoever is signed in. */
function projectOwner(p){return projectsModel.ownerOf(p,team);}
function ownerAvatar(p){const o=projectOwner(p);return `<span class="avatar sm owner" role="img" aria-label="${esc(o?'Owner: '+o.name:'No owner yet')}" title="${esc(o?o.name:'No owner yet')}">${esc(o?o.initial:'–')}</span>`;}
function ownerChip(p){const o=projectOwner(p);return o?`<span class="person-chip"><span class="avatar sm owner">${esc(o.initial)}</span>${esc(o.name)}</span>`:'<span class="quiet-text">No owner yet</span>';}

/* Overview: actionable personal focus and cross-app work. */
/* Every activity entry the store holds, each leading to its record. */
function activityPage(){const items=workspaceActivity.map(a=>overviewModel.activityItem(a,{tickets,projects,contacts,companies:(window.workspaceStore&&workspaceStore.state.companies)||[],invoices}));return detailHeader('overview','Overview','Recent activity','What changed across the studio, newest first.')+`<section class="panel"><div class="activity-list activity-page">${items.map(activityRow).join('')||'<p class="quiet-text">Nothing yet. Activity appears here as tickets, projects and contacts change.</p>'}</div></section>`;}
/* Money is for owners and admins. The menu no longer offers Finance to anyone
   else, and a link that still leads here says why instead of showing zeros. */
function financeClosed(){return titlebar('Finance is for owners and admins.','Revenue, invoices and payouts are shown only to the people who run the studio’s money.')+`<section class="panel">${empty('Nothing to show here','Ask an owner or an admin if you need a figure from Finance.')}</section>`;}
/* "My focus" is your unticked tasks on work that is still moving, soonest
   first (overview-model.js focusTasks). It used to be the first three unticked
   tasks of any project, whoever they were for — and an old patch gave any
   project at 72% the first project's task count. */
overview = function(){if(routeParts[1]==='activity')return activityPage();const base=originalOverview();const me=window.workspaceSession&&workspaceSession.employee;const focus=overviewModel.focusTasks(projects,me&&me.id,{isActive:projectsModel.isActive,today:CAL.dayKey(new Date())});const counts=overviewCounts();const summary=[counts.ticketsOpen==null?'':overviewModel.plural(counts.ticketsOpen,'open ticket'),counts.projectsActive==null?'':overviewModel.plural(counts.projectsActive,'active project')].filter(Boolean).join(' · ');const block=`<section class="panel focus-panel"><div class="focus-intro"><span class="eyebrow">MY FOCUS</span><h2>Move your day forward.</h2><p>${esc(summary)}</p></div><div class="focus-items">${focus.map(f=>`<div class="focus-item"><label><input type="checkbox" data-project-task="${esc(f.projectId)}" data-task="${f.index}" data-task-id="${esc(f.taskId||'')}"><span>${esc(f.title)}</span>${f.due?`<small class="focus-due${f.overdue?' overdue':''}">${f.overdue?'Overdue':'Due'} ${esc(f.due)}</small>`:''}</label>${link('projects/'+f.projectId+'/tasks',f.projectName,'chevron')}</div>`).join('')||`<p class="quiet-text">${me?'Nothing assigned to you on active projects.':'Your tasks show here once you are signed in.'}</p>`}</div></section>`;return base.replace('<div class="metrics">',block+'<div class="metrics">');};

/* Ticket queues and a ticket's page: tickets-ui.js. */

/* Mail: mailboxes, folders, conversations and the reading pane live in mail.js. */

/* Projects: board, list and full task workspaces. */
projectsView = function(){if(routeParts[1]!==undefined)return projectDetail(String(routeParts[1]));const list=projects.filter(p=>matches(queries.projects,p.name,p.client));return titlebar('Make room for good work.','Products, client work, and everything moving toward launch.',createButton('New project','projects'))+statStrip([['Active projects',projects.filter(projectsModel.isActive).length,'Across the studio'],['In review',projects.filter(p=>p.status==='In review').length,'Ready for a closer look'],['Open tasks',projects.reduce((a,p)=>a+p.tasks.length-checkedTasks(p),0),'Across all projects'],['Completed tasks',projects.reduce((a,p)=>a+checkedTasks(p),0),'Done so far']])+`<div class="view-toolbar">${segments([['board','Board'],['list','List']],projectMode,'projectMode')}${queryInput('projects','Search projects')}</div>${projectMode==='board'?`<div class="project-board stage-board">${projectsModel.boardColumns(list).map(({status,projects:items})=>`<section class="board-column"><div class="board-heading"><h2>${status}</h2>${countTag(items.length)}</div><div class="board-cards">${items.map(p=>projectTile(p)).join('')||'<div class="board-empty">No projects in this stage.</div>'}</div></section>`).join('')}</div>`:`<section class="panel"><div class="table-wrap"><table class="module-table"><thead><tr><th>Project</th><th>Status</th><th>Tasks</th><th>Due</th></tr></thead><tbody>${list.map(p=>`<tr data-action="project" data-id="${p.id}" role="button" tabindex="0"><td><div class="cell-main"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.client)}</small></div></div></td><td>${pill(p.status)}</td><td>${checkedTasks(p)} / ${p.tasks.length}</td><td>${esc(p.due)}</td></tr>`).join('')}</tbody></table>${!list.length?empty('No projects found','Try another search.'):''}</div></section>`}`;};
function projectTile(p){return `<a class="project-card board-card" href="#projects/${p.id}"><div class="card-top"><div class="project-logo ${p.style}">${esc(p.initial)}</div><span class="card-arrow">${icon('chevron')}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="card-task-progress"><span>${checkedTasks(p)} of ${p.tasks.length} tasks complete</span><span>${p.tasks.length?Math.round(checkedTasks(p)/p.tasks.length*100):0}%</span></div><div class="progress"><i style="width:${p.tasks.length?checkedTasks(p)/p.tasks.length*100:0}%"></i></div><div class="project-card-bottom">${ownerAvatar(p)}${p.due?`<span>Due ${esc(p.due)}</span>`:''}</div></a>`;}
function projectDetail(id){const p=projects.find(p=>p.id===id);if(!p)return notFound();const tab=routeParts[2]||'overview';const byCompany=p.companyId?contacts.findIndex(c=>c.row&&c.row.company&&c.row.company.id===p.companyId):-1;const ci=byCompany;const related=projectsModel.projectTickets(tickets,p);const meetings=projectsModel.upcomingEvents((window.workspaceStore&&workspaceStore.state.projectEvents)||[],p,Date.now());const taskPanel=tasksUi.panel(p);return detailHeader('projects','All projects',p.name,p.client,pill(p.status)+(typeof projectsUi!=='undefined'?projectsUi.actions(p):''))+subnav([['projects/'+id,'Overview','overview'],['projects/'+id+'/tasks','Tasks','tasks'],['projects/'+id+'/files','Files','files'],['projects/'+id+'/notes','Notes','notes']],tab)+`<div class="record-layout"><div class="record-main">${tab==='notes'?notesPanel('projects',id):tab==='tasks'?taskPanel:tab==='files'&&typeof projectPanels!=='undefined'?projectPanels.filesPanel(p):`<section class="panel project-summary"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><span class="eyebrow">PROJECT BRIEF</span><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p></div><div class="project-completion"><strong>${checkedTasks(p)}<span> / ${p.tasks.length}</span></strong><small>tasks complete</small></div></section>${taskPanel}`}</div><aside class="record-aside">${properties([['Status',selectField('Project status','projects',id,'status',projectsModel.STATUS_LABELS,p.status)],['Owner',ownerChip(p)],['Starts',esc(p.starts||'Not set')],['Due date',esc(p.due||'Not set')],['Client / product',esc(p.client)],...(typeof projectPanels!=='undefined'?projectPanels.budgetRows(p):[])])}${typeof projectPanels!=='undefined'?projectPanels.teamPanel(p)+projectPanels.peoplePanel(p):''}${linkedPanel('Connected work',[...(ci>=0?[[`crm/${contacts[ci].id}`,contacts[ci].name,p.client,'crm']]:[]),...related.map(t=>[`tickets/${t.id}`,t.title,'VYG-'+t.id+' · '+t.status+(t.row&&t.row.project_id?'':' · not filed under a project'),'tickets'])])}${linkedPanel('Meetings',meetings.map(ev=>[events.some(e=>e.id===ev.id)?'agenda/'+ev.id:'agenda',ev.title,ev.when,'agenda']))}</aside></div>`;}

/* CRM: the pipeline, the companies and contacts, and their pages are drawn by crm-ui.js. */

/* Agenda: the week, a day, the schedule and an event's page are drawn by agenda-ui.js. */

/* Finance: the figures, the invoice list and an invoice's page — finance-ui.js. */

/* Company: people, studio profile and workspace preferences. */
/* Empty for the same reason as the arrays in app.js: the store fills them. */

companyView = function(){if(routeParts[1]==='people')return personDetail(String(routeParts[2]));companyTab=['studio','preferences'].includes(routeParts[1])?routeParts[1]:'team';return titlebar('The studio behind the work.','People, company details, and your workspace.')+subnav([['company','People','team'],['company/studio','Studio','studio'],['company/preferences','Preferences','preferences']],companyTab)+(companyTab==='team'?`<div class="people-grid">${team.map(p=>`<a href="#company/people/${esc(p.id)}" class="panel person-card"><div class="person-cover"><div class="avatar ${p.row&&p.row.role==='owner'?'owner':''}">${esc(p.initial)}</div></div><div class="person-info"><div class="section-title"><h2>${esc(p.name)}</h2>${icon('chevron')}</div><p>${esc(p.role)}</p><span class="pill ${p.row&&p.row.role==='owner'?'blue':'purple'}">${esc(p.tag)}</span><div class="person-work-count"><span>${tickets.filter(t=>ticketsModel.assigneeOf(t)===p.id&&ticketsModel.isOpen(t)).length} open tickets</span><span>${projects.filter(pr=>pr.ownerId===p.id).length} owned projects</span></div></div></a>`).join('')}<section class="panel team-context"><span class="eyebrow">VEYAGO INC.</span><h2>A shared place to work.</h2><p>The same conversations, project tasks, and client context—available across your workspace.</p>${link('company/studio','View studio details','arrow')}</section></div>`:companyTab==='studio'?`<div class="record-layout"><div class="record-main"><section class="panel content-panel studio-profile"><span class="brand-glyph">V</span><h2>Veyago Inc.</h2><p class="body-copy">Independent software studio. Software for the journey.</p><div class="studio-facts"><div><span>Location</span><strong>New York, United States</strong></div><div><span>Contact</span><strong>hello@veyago.cloud</strong></div></div><a class="btn" href="https://www.veyago.cloud/" target="_blank" rel="noopener">Company website ${icon('external')}</a></section>${linkedPanel('Products',projects.filter(p=>p.client==='Internal product').map(p=>[`projects/${p.id}`,p.name,p.status,'projects']))}</div><aside class="record-aside"><section class="panel content-panel"><h2>Workspace apps</h2>${overviewModel.visibleNavs(navs,isManagerNow()).filter(([id])=>id!=='overview'&&id!=='company').map(([id,label])=>`<a class="studio-app" href="#${id}">${icon(id)}<span>${label}</span>${icon('chevron')}</a>`).join('')}</section></aside></div>`:`<section class="panel preferences-panel"><div class="preference-heading"><h2>Workspace appearance</h2><p>These preferences apply to this browser.</p></div><div class="preference-row"><div><h3>Compact spacing</h3><p>Fit more records into your working view.</p></div><label class="switch"><input id="compact-setting" type="checkbox" ${document.body.classList.contains('compact')?'checked':''} aria-label="Compact spacing"><span></span></label></div><div class="preference-row"><div><h3>Motion effects</h3><p>Animate subtle transitions between views.</p></div><label class="switch"><input id="motion-setting" type="checkbox" ${!document.body.classList.contains('no-motion')?'checked':''} aria-label="Motion effects"><span></span></label></div><div class="preference-heading"><h2>Your account</h2><p>Your password and two-factor sign-in are kept in the admin.</p></div><div class="preference-row"><div><h3>Password and two-factor</h3><p>Change your password, or turn on codes from an authenticator app.</p></div><a class="btn" href="${esc(window.VEYAGO_ACCOUNT_URL||'https://veyago.cloud/admin/account/')}" target="_blank" rel="noopener">Open account ${icon('external')}</a></div><div class="preference-heading"><h2>Keyboard</h2><p>Shortcuts that work anywhere in the workspace.</p></div><div class="shortcut-row"><span>Search workspace</span><kbd>/</kbd></div><div class="shortcut-row"><span>Close dialog or search</span><kbd>esc</kbd></div></section>`);};
function personDetail(id){const p=team.find(m=>m.id===id);if(!p)return notFound();const assigned=tickets.filter(t=>ticketsModel.assigneeOf(t)===p.id);const isOwner=Boolean(p.row&&p.row.role==='owner');return detailHeader('company','People',p.name,p.role)+`<div class="record-layout"><div class="record-main"><section class="panel contact-summary"><div class="avatar contact-avatar ${isOwner?'owner':''}">${esc(p.initial)}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.focus)}</p></div>${pill(p.tag,'blue')}</section>${linkedPanel('Assigned tickets',assigned.map(t=>[`tickets/${t.id}`,t.title,t.status,'tickets']))}${linkedPanel('Owned projects',projects.filter(pr=>pr.ownerId===p.id).map(pr=>[`projects/${pr.id}`,pr.name,pr.status,'projects']))}</div><aside class="record-aside">${properties([['Role',esc(p.role)],['Open tickets',assigned.filter(t=>ticketsModel.isOpen(t)).length],['Workspace','Veyago Inc.']])}</aside></div>`;}

/* Routes and transitions. Existing create, compose and search workflows remain available. */
showTicket = id => {modal.close();navigate('tickets/'+id);};
showProject = id => {modal.close();navigate('projects/'+id);};
showContact = id => {modal.close();navigate('crm/'+id);};
action = function(name,id){if(name==='invoice'){modal.close();navigate('finance/'+id);return;}originalAction(name,id);};
/* The breadcrumb names the record and links back to its list — a record page
   used to say "Details", whatever it was (overview-model.js crumb). */
render = function(){nav();const label=navs.find(n=>n[0]===page)?.[1]||'Overview';const c=overviewModel.crumb(page,routeParts,{labels:Object.fromEntries(navs),tickets,projects,contacts,companies:(window.workspaceStore&&workspaceStore.state.companies)||[],events:events.concat((window.workspaceStore&&workspaceStore.state.projectEvents)||[]),invoices,team,mailFolder,open:overviewModel.canOpen(page,isManagerNow()),has:key=>Boolean(window.workspaceStore&&workspaceStore.has(key)),event:id=>window.workspaceStore&&typeof workspaceStore.askEvent==='function'?workspaceStore.askEvent(id):null});document.querySelector('#breadcrumb').innerHTML=c.parent?`<a href="#${esc(c.parent.route)}">${esc(c.parent.label)}</a><span>/</span>${esc(c.current)}`:esc(c.current);document.querySelector('#main').innerHTML=overviewModel.canOpen(page,isManagerNow())?({overview,tickets:ticketsView,mail:mailView,projects:projectsView,crm:crmView,agenda:agendaView,finance:financeView,company:companyView}[page])():financeClosed();document.title=(c.parent?c.current+' · ':'')+label+' — Veyago Workspace';};
/* A new page takes focus to its heading, so someone on a keyboard or a screen
   reader starts at the top of it rather than back on <body>. Moving between
   conversations inside Mail leaves focus in the list, and the first page of a
   visit does not take focus from the browser. */
let firstNavigation=true;
function focusNewPage(before){if(firstNavigation){firstNavigation=false;return;}const now=shellModel.pageKey(page,routeParts);if(now===before||(page==='mail'&&before.startsWith('mail/')))return;const heading=document.querySelector('#main h1');if(!heading)return;heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}
/* A link to a #hash fires both hashchange and popstate, so the same route
   arrives twice. The second time the page is only repainted, keeping focus —
   rebuilding it outright threw away the heading the first had just focused. */
navigate = function(target){if(modal.open)modal.close();const parts=String(target||'overview').split('/');if(!navs.some(n=>n[0]===parts[0]))return;if(!firstNavigation&&page===parts[0]&&routeParts.join('/')===parts.join('/')){if(document.querySelector('#sidebar').classList.contains('open'))setMenu(false,{returnFocus:true});repaintKeepingFocus();return;}const before=shellModel.pageKey(page,routeParts);page=parts[0];routeParts=parts;const hash='#'+parts.join('/');if(location.hash!==hash)history.pushState(null,'',hash);setMenu(false);render();window.scrollTo(0,0);focusNewPage(before);};
window.addEventListener('popstate',()=>navigate(location.hash.slice(1)));
const routeBeforeInit=location.hash.slice(1);
try{document.body.classList.toggle('compact',localStorage.getItem('veyago-compact')==='true');document.body.classList.toggle('no-motion',localStorage.getItem('veyago-motion')==='false');}catch{}
function redrawPreservingFocus(input){const name=input.dataset.query,start=input.selectionStart;render();const next=document.querySelector(`[data-query="${name}"]`);if(next){next.focus();if(next.setSelectionRange){try{next.setSelectionRange(start,start);}catch{}}}}
document.addEventListener('input',e=>{if(e.target.matches('[data-query]')){queries[e.target.dataset.query]=e.target.value;redrawPreservingFocus(e.target);}});
/* Showing images is a per-message decision the reader makes, not a setting
   they set once and forget. It resets on reload, deliberately. */
document.addEventListener('click', e => {
  const btn = e.target.closest?.('[data-show-images]');
  if (!btn) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  window.__mailShowImages = [...(window.__mailShowImages || []), btn.dataset.showImages];
  render();
}, true);

document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){const {view:key,value}=view.dataset;if(key==='ticketScope')ticketScope=value;if(key==='projectMode')projectMode=value;if(key==='agendaMode')agendaMode=value;repaintKeepingFocus();return;}const star=e.target.closest('[data-star]');if(star){mails[Number(star.dataset.star)].starred=!mails[Number(star.dataset.star)].starred;render();return;}if(e.target.closest('[data-print-invoice]'))window.print();});
document.addEventListener('change',e=>{const target=e.target;if(target.matches('[data-project-task]')){e.stopImmediatePropagation();const p=projects.find(p=>String(p.id)===target.dataset.projectTask),i=Number(target.dataset.task);p.checked??=[];p.checked=target.checked?[...new Set([...p.checked,i])]:p.checked.filter(n=>n!==i);activityRecord((target.checked?'Completed: ':'Reopened: ')+p.tasks[i]);render();toast(target.checked?'Task completed':'Task reopened');return;}if(target.matches('[data-record-kind]')){const {recordKind:kind,recordId,field}=target.dataset;const collection={tickets,projects,crm:contacts}[kind];const record=collection.find(r=>String(r.id)===String(recordId));if(record){record[field]=target.value;activityRecord('Updated '+(record.title||record.name));render();toast('Updated in this demo session');}return;}if(target.id==='compact-setting'||target.id==='motion-setting'){const compact=target.id==='compact-setting';document.body.classList.toggle(compact?'compact':'no-motion',compact?target.checked:!target.checked);try{localStorage.setItem(compact?'veyago-compact':'veyago-motion',String(target.checked));}catch{}toast('Preference updated');}},true);
/* Notes and ticket replies are saved by data/writes.js, and tasks added by tasks-ui.js. */

projectRows = function(){
/* Work that is still moving, soonest due first (overview-model.js). It used to
   be the first three projects in an order that was the same for everyone, so a
   paused project could sit on the Overview as "active". */
const active=overviewModel.activeProjects(projects,projectsModel.isActive);
const today=CAL.dayKey(new Date());
if(!active.length)return `<p class="quiet-text" style="padding:4px 19px 20px">${projects.length?'Nothing active right now. Paused and finished work is on the Projects page.':'No projects yet. Create one and it will show here with its progress.'}</p>`;
return `<div class="project-list">${active.map(p=>`<a class="project-row" href="#projects/${esc(p.id)}"><div class="project-logo ${p.style}">${esc(p.initial)}</div><div><div class="project-name">${esc(p.name)}</div><div class="project-meta">${esc(p.client)}${p.due?` · <span class="${p.dueOn&&p.dueOn<today?'overdue':''}">${p.dueOn&&p.dueOn<today?'Overdue, due':'Due'} ${esc(p.due)}</span>`:''}</div></div><div><div class="progress-caption">${checkedTasks(p)} / ${p.tasks.length} tasks</div><div class="progress"><i style="width:${p.tasks.length?checkedTasks(p)/p.tasks.length*100:0}%"></i></div></div>${ownerAvatar(p)}</a>`).join('')}</div>`;};
/* the notifications bell is handled in app.js, from live data */

navigate(routeBeforeInit||'overview');
